oxy_webhelp_navlinks = {"aws_dynamodb_recovery-d39536e19841":{"topics":[{"title":"Recovery options for Amazon DynamoDB","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides three recovery options for Amazon DynamoDB tables:         point-in-time recovery for precise data restoration, snapshot recovery for flexible data         management, and granular search and in-place recovery for restoring individual         records.<\/p>","href":"saas\/aws_dynamodb_recovery_options.html","attributes":{"data-id":"aws_dynamodb_recovery_options"},"menu":{"hasChildren":false},"tocID":"aws_dynamodb_recovery_options-d39536e19855","topics":[]},{"title":"Networking requirements for Amazon DynamoDB recovery","shortdesc":"<p class=\"shortdesc\">You can ensure successful Amazon DynamoDB recovery by considering key networking         requirements such as provisioned Write Capacity Units, VPC configuration, security group         settings, and NACLs.<\/p>","href":"saas\/aws_dynamodb_recv_network_reqs.html","attributes":{"data-id":"aws_dynamodb_recv_network_reqs"},"menu":{"hasChildren":false},"tocID":"aws_dynamodb_recv_network_reqs-d39536e19868","topics":[]},{"title":"Performing point-in-time recovery for Amazon DynamoDB","shortdesc":"<p class=\"shortdesc\">Perform a point-in-time recovery for an Amazon DynamoDB table to restore data to a         specific point in time using continuous backups, with the ability to create the new table in         a different AWS region.<\/p>","href":"saas\/aws_dynamodb_performing_pitr.html","attributes":{"data-id":"aws_dynamodb_performing_pitr"},"menu":{"hasChildren":false},"tocID":"aws_dynamodb_performing_pitr-d39536e19879","topics":[]},{"title":"Performing snapshot recovery for Amazon DynamoDB","shortdesc":"<p class=\"shortdesc\">Perform a snapshot recovery for an Amazon DynamoDB table to recover data using either         an on-demand snapshot or a scheduled snapshot taken according to the assigned SLA         Domain.<\/p>","href":"saas\/aws_dynamodb_performing_snapshot_recv.html","attributes":{"data-id":"aws_dynamodb_performing_snapshot_recv"},"menu":{"hasChildren":false},"tocID":"aws_dynamodb_performing_snapshot_recv-d39536e19890","topics":[]},{"title":"Searching Amazon DynamoDB snapshot records","shortdesc":"<p class=\"shortdesc\">Search for specific records in Amazon DynamoDB snapshots using partition key and         optional attribute filters, then preview or export the matched results.<\/p>","href":"saas\/aws_dynamodb_searching_snapshot_records.html","attributes":{"data-id":"aws_dynamodb_searching_snapshot_records"},"menu":{"hasChildren":false},"tocID":"aws_dynamodb_searching_snapshot_records-d39536e19901","topics":[]},{"title":"Restoring Amazon DynamoDB records in place","shortdesc":"<p class=\"shortdesc\">Restore specific records from an Amazon DynamoDB snapshot directly to the source         table without creating a new table.<\/p>","href":"saas\/aws_dynamodb_inplace_records_recovery.html","attributes":{"data-id":"aws_dynamodb_inplace_records_recovery"},"menu":{"hasChildren":false},"tocID":"aws_dynamodb_inplace_records_recovery-d39536e19912","topics":[]},{"title":"Recovering specific Amazon DynamoDB records from a snapshot","shortdesc":"<p class=\"shortdesc\">Search for and restore specific records from a selected Amazon DynamoDB snapshot         directly to the source table, without performing a full-table recovery.<\/p>","href":"saas\/aws_dynamodb_snapshot_records_recovery.html","attributes":{"data-id":"aws_dynamodb_snapshot_records_recovery"},"menu":{"hasChildren":false},"tocID":"aws_dynamodb_snapshot_records_recovery-d39536e19923","topics":[]},{"title":"Limitations for Amazon DynamoDB granular search and recovery","shortdesc":"<p class=\"shortdesc\">Information about limitations that apply when you search Amazon DynamoDB snapshot         records and restore records in place.<\/p>","href":"saas\/aws_dynamodb_granular_recv_limitations.html","attributes":{"data-id":"aws_dynamodb_granular_recv_limitations"},"menu":{"hasChildren":false},"tocID":"aws_dynamodb_granular_recv_limitations-d39536e19934","topics":[]}]}};